-- Restructured "Sobre el destino" for every published trip (2026-11-20).
-- Same layout as the Christmas trips: intro, De un vistazo (table), La ruta (map), Bueno saber, credits.
-- Insert-only form (on conflict update) so it runs in the Supabase SQL editor or MCP.
-- Only the description column changes. Christmas trips keep their text and credits; the
-- table and map are spliced in after their intro paragraphs.
begin;

insert into public.tours (slug, title, description) values ('el-reto-del-pirineo-exploracion-de-queralbs-y-el-mitico-vall-de-nuria', 'x', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Queralbs y la Vall de Núria son dos de los paisajes más emblemáticos del Pirineo catalán, en la comarca del Ripollès. Empezamos en Queralbs, un pueblo de casas de piedra y tejados de pizarra a 1.220 metros de altitud, documentado desde el año 839. Paseamos por su patrimonio, con la iglesia de Sant Jaume (siglo X) y el ayuntamiento, antes de la gran subida."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Desde allí subimos en tren cremallera, porque al valle no se puede llegar en coche. Arriba, a casi 2.000 metros y rodeados de picos que alcanzan los 3.000, tenemos senderismo, deportes de aventura y actividades en grupo, además del histórico Santuario de Núria."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "El billete del cremallera y la subida en telecabina dentro del valle están incluidos en el precio, así que solo tienes que disfrutar de las vistas."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "De un vistazo"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Dato"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Detalle"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Zona"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ripollès, Pirineo catalán"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Queralbs"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "1.220 m de altitud, documentado desde el año 839"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vall de Núria"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Casi 2.000 m, rodeado de picos de hasta 3.000 m"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Acceso al valle"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tren cremallera (no se puede subir en coche)"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Incluido"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Autocar ida y vuelta, guía acompañante, cremallera ida y vuelta y telecabina en el valle"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Por tu cuenta"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Comida y bebida"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "La ruta"}]}, {"type": "routeMap", "attrs": {"title": "Queralbs → Vall de Núria", "points": [{"name": "Queralbs", "lat": 42.2706, "lng": 2.1636}, {"name": "Santuario de Núria", "lat": 42.3973, "lng": 2.1533}]}}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bueno saber"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Para los más aventureros hay la opción de subir a pie desde Queralbs: unas 4 horas, nivel medio y 800 metros de desnivel."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "El cremallera y la telecabina del valle ya están pagados: no tendrás que comprar billetes."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A casi 2.000 metros refresca: lleva ropa de abrigo y calzado cómodo."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La comida y la bebida corren por tu cuenta."}]}]}]}]}'::jsonb)
  on conflict (slug) do update set description = excluded.description;

insert into public.tours (slug, title, description) values ('el-canon-del-vero-alquezar-y-la-ruta-de-las-pasarelas', 'x', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cruzamos a Aragón para llegar a Alquézar, en el corazón del Somontano y del Parque Natural de la Sierra y los Cañones de Guara. Considerado uno de los pueblos más bonitos de España, Alquézar se levanta sobre una roca, coronado por la Colegiata de Santa María y los restos de su castillo de origen musulmán. Lo recorremos en grupo por sus calles empedradas, sus plazas porticadas y sus miradores sobre el cañón."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Después bajamos al río para la gran aventura del día: la Ruta de las Pasarelas del río Vero. Es un recorrido circular por pasarelas metálicas ancladas a las paredes del cañón, escaleras y puentes colgados sobre aguas de color turquesa, junto a cascadas, presas centenarias y enormes abrigos de roca. Durante la ruta es habitual ver buitres leonados sobrevolando el cañón."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Paramos a comer y tenemos tiempo libre para disfrutar de Alquézar antes de volver a Barcelona. Nuestro guía acompaña al grupo durante todo el día."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "De un vistazo"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Dato"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Detalle"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Zona"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Somontano, Huesca (Aragón)"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Espacio natural"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Parque Natural de la Sierra y los Cañones de Guara"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Trayecto"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Unas 3 horas en autocar, con una parada técnica"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ruta a pie"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pasarelas del río Vero, recorrido circular"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Incluido"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Autocar ida y vuelta y guía acompañante todo el día"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Por tu cuenta"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Comida y bebida"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "La ruta"}]}, {"type": "routeMap", "attrs": {"title": "Barcelona → Alquézar y el río Vero", "points": [{"name": "Barcelona (Estació del Nord)", "lat": 41.3953, "lng": 2.183}, {"name": "Alquézar y Pasarelas del río Vero", "lat": 42.1717, "lng": 0.0244}]}}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bueno saber"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "En invierno, la apertura de las pasarelas depende del tiempo y del caudal del río. Si no se pueden recorrer, hacemos una ruta alternativa por los miradores y senderos del cañón del Vero."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lleva calzado de montaña y ropa de abrigo."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La comida no está incluida: puedes traer picnic o comer en los bares y restaurantes del pueblo."}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Créditos de las fotos"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Fotos: FrDr, Robot8A, Mikipons, McBodes, Augustin Liviu, Alberto-g-rovi, Pedro José Ponce Asensio, Enric, LSanzSal — Wikimedia Commons (licencias CC BY / CC BY-SA)."}]}]}'::jsonb)
  on conflict (slug) do update set description = excluded.description;

insert into public.tours (slug, title, description) values ('el-corazon-salvaje-del-pirineo-aiguestortes-y-el-lago-de-sant-maurici', 'x', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nos adentramos en el corazón de los Pirineos Centrales, en el Parque Nacional de Aigüestortes i Estany de Sant Maurici. Declarado parque nacional el 21 de octubre de 1955, es el único de Cataluña y uno de los más emblemáticos de España. Ocupa más de 40.000 hectáreas en la provincia de Lleida, entre la Alta Ribagorça, el Pallars Sobirà, el Pallars Jussà y el Valle de Arán."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Su nombre significa «aguas tortuosas», por los ríos, arroyos y canales que serpentean por sus valles. Es un paisaje de origen glaciar, con más de 200 lagos (estanys), bosques de abetos y hayas y picos de más de 3.000 metros."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Llegamos en autocar a Espot y subimos en taxi 4x4 hasta el Estany de Sant Maurici, el lugar más icónico del parque, a los pies de Els Encantats, dos montañas gemelas de forma puntiaguda. Allí paseamos junto al lago, con tiempo para el senderismo y la fotografía."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "De un vistazo"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Dato"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Detalle"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Parque"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Parque Nacional desde 1955, el único de Cataluña"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Superficie"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Más de 40.000 hectáreas (Lleida)"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lagos"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Más de 200 estanys de origen glaciar"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cumbres"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Picos de más de 3.000 m"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sant Maurici y Els Encantats"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Unos 1.910 m de altitud"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Incluido"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Autocar ida y vuelta, guía acompañante y taxi 4x4 Espot – Estany de Sant Maurici"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Por tu cuenta"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Comida y bebida"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "La ruta"}]}, {"type": "routeMap", "attrs": {"title": "Espot → Estany de Sant Maurici", "points": [{"name": "Espot", "lat": 42.5764, "lng": 1.0872}, {"name": "Estany de Sant Maurici", "lat": 42.5815, "lng": 1.0009}]}}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bueno saber"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "El tramo de Espot al Estany de Sant Maurici se hace en taxi 4x4, incluido en el precio."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cerca de los 2.000 metros refresca: lleva ropa de abrigo y calzado cómodo."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La comida y la bebida corren por tu cuenta."}]}]}]}]}'::jsonb)
  on conflict (slug) do update set description = excluded.description;

insert into public.tours (slug, title, description) values ('la-magia-rural-de-cataluna-escapada-a-rupit-y-tavertet', 'x', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Una escapada al Collsacabra, en Osona, para descubrir dos de los pueblos con más encanto de la Cataluña rural. Empezamos en Rupit, un pueblo medieval que ONU Turismo incluyó entre los «Best Tourism Villages», los mejores pueblos turísticos del mundo. Sus calles estrechas, sus casas de piedra y sus puentes colgantes parecen detenidos en el tiempo."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Después seguimos hasta Tavertet, un pueblo asomado a lo alto de un peñasco. Es un mirador natural con vistas panorámicas sobre los pantanos de Sau y Susqueda y, en el horizonte, la sierra del Montseny: el sitio perfecto para las fotos de grupo."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "De un vistazo"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Dato"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Detalle"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Zona"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Collsacabra, Osona"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rupit"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pueblo medieval, en la lista «Best Tourism Villages» de ONU Turismo"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tavertet"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pueblo sobre un acantilado, mirador sobre Sau, Susqueda y el Montseny"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Incluido"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Autocar ida y vuelta y guía acompañante"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Por tu cuenta"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Comida y bebida"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "La ruta"}]}, {"type": "routeMap", "attrs": {"title": "Rupit → Tavertet", "points": [{"name": "Rupit", "lat": 42.0244, "lng": 2.4661}, {"name": "Tavertet", "lat": 41.9961, "lng": 2.4183}]}}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bueno saber"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rupit tiene calles empedradas y puentes colgantes: mejor con calzado cómodo."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La comida y la bebida corren por tu cuenta."}]}]}]}]}'::jsonb)
  on conflict (slug) do update set description = excluded.description;

insert into public.tours (slug, title, description) values ('la-ruta-del-fuego-exploracion-en-fageda-den-jorda-y-castellfollit-de-la-roca', 'x', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Un día entre volcanes en La Garrotxa, la comarca de Girona rodeada por 21 cráteres volcánicos. Empezamos en la Fageda d''en Jordà, un hayedo a 550 metros de altitud que crece sobre una antigua colada de lava del volcán Croscat. Es un terreno poco frecuente en la península Ibérica que ha inspirado a artistas e historiadores."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Seguimos hasta el volcán de Santa Margarida por parte del itinerario 3. Su explosión dejó un cráter ancho y circular, hoy un prado con una ermita románica en el interior, y el resto del volcán está cubierto de bosques caducifolios."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Terminamos en Castellfollit de la Roca, uno de los pueblos más pequeños y fascinantes de la provincia de Girona. Se asienta al borde de un precipicio de basalto de 50 metros, esculpido por el río Fluvià sobre dos coladas de lava superpuestas. Su casco antiguo, de piedra volcánica, se remonta al siglo XI y lo recorremos desde la calle principal hasta el mirador de Josep Pla."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "De un vistazo"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Dato"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Detalle"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Zona"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La Garrotxa (Girona), con 21 cráteres volcánicos"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fageda d''en Jordà"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hayedo a 550 m sobre la colada de lava del Croscat"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Volcán de Santa Margarida"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cráter circular con una ermita románica"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Castellfollit de la Roca"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Acantilado de basalto de 50 m, casco antiguo del siglo XI"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Incluido"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Autocar ida y vuelta y guía acompañante"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Por tu cuenta"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Comida y bebida"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "La ruta"}]}, {"type": "routeMap", "attrs": {"title": "Fageda d''en Jordà → Santa Margarida → Castellfollit", "points": [{"name": "Fageda d''en Jordà", "lat": 42.1546, "lng": 2.5108}, {"name": "Volcán de Santa Margarida", "lat": 42.1452, "lng": 2.5392}, {"name": "Castellfollit de la Roca", "lat": 42.2197, "lng": 2.5508}]}}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bueno saber"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Caminamos por el bosque y hasta el cráter: lleva calzado cómodo."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La comida y la bebida corren por tu cuenta."}]}]}]}]}'::jsonb)
  on conflict (slug) do update set description = excluded.description;

